mapper.select:
SELECT a.id ,a.main_id ,a.attachment_category ,a.original_file_name ,a.file_type ,a.file_size ,a.content_type ,a.full_url ,a.source_attachment_id ,s.main_id AS source_report_id ,CASE s.table_name WHEN 'rrs_report_in' THEN 'internal' WHEN 'rrs_report_out' THEN 'external' END AS source_report_source ,CASE s.table_name WHEN 'rrs_report_in' THEN ri.report_title WHEN 'rrs_report_out' THEN ro.report_title END AS source_report_title FROM sys_attachment a LEFT JOIN sys_attachment s ON s.id = a.source_attachment_id LEFT JOIN rrs_report_in ri ON s.table_name = 'rrs_report_in' AND ri.id = s.main_id LEFT JOIN rrs_report_out ro ON s.table_name = 'rrs_report_out' AND ro.id = s.main_id WHERE a.table_name = #{tableName} AND a.main_id IN
#{adjustLogId}
AND a.is_deleted = 0 ORDER BY a.main_id ASC ,a.id ASC

SELECT COUNT(1) FROM sys_attachment a WHERE a.file_name = #{fileName} AND a.is_deleted = 0 AND ( (a.table_name = 'rrs_report_in' AND a.attachment_category = 'report_in' AND EXISTS (SELECT 1 FROM rrs_report_in ri WHERE ri.id = a.main_id AND ri.is_deleted = 0 AND ri.security_code = #{stockCode} AND ri.security_type = 'stock'))
OR (a.table_name = 'rrs_report_out' AND a.attachment_category = 'report_out' AND EXISTS (SELECT 1 FROM rrs_report_out ro WHERE ro.id = a.main_id AND ro.is_deleted = 0 AND ro.security_code = #{stockCode} AND ro.security_type = 'stock'))
)
